ub.com/repos/jabbour-labs/patientrecords.pub/git/trees/b8f7df91a2ef6b5c8b6ad33d3e6dc30e0c57d236"},"url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/commits/78f4c9e381c6dc0853ba5cf7bb8220a153dfbb2f","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/78f4c9e381c6dc0853ba5cf7bb8220a153dfbb2f","node_id":"C_kwDORpn-rNoAKDc4ZjRjOWUzODFjNmRjMDg1M2JhNWNmN2JiODIyMGExNTNkZmJiMmY","parents":[{"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/d53e276bbb9bd553270698f73b7de9f88fa618e9","sha":"d53e276bbb9bd553270698f73b7de9f88fa618e9","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/d53e276bbb9bd553270698f73b7de9f88fa618e9"}],"sha":"78f4c9e381c6dc0853ba5cf7bb8220a153dfbb2f","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/78f4c9e381c6dc0853ba5cf7bb8220a153dfbb2f"},{"author":null,"comments_url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/d53e276bbb9bd553270698f73b7de9f88fa618e9/comments","commit":{"author":{"date":"2026-02-26T16:01:51Z","email":"dev@patientrecords.local","name":"Development Team"},"comment_count":0,"committer":{"date":"2026-02-26T16:01:51Z","email":"dev@patientrecords.local","name":"Development Team"},"message":"Refactor demographics to structured object schema\n\n- Backend: Transform demographics from array to object with comprehensive fields\n  * Add structured demographics object with address, insurance, emergency contacts\n  * Add identity fields (SSN, MRN, blood type, sex assigned at birth)\n  * Add cultural/social fields (race, ethnicity, marital status, preferred language)\n  * Update seed data with 5 varied patient profiles\n  * Add support for primary/secondary/tertiary insurance\n  * Add emergency contacts with relationship and primary flag\n\n- Frontend - Demographics Module: Complete UI overhaul\n  * Refactor component to use new Demographics interface\n  * Create CollapsibleSectionComponent for organized content\n  * Add collapsible sections: Contact Info, Emergency Contacts, Cultural/Social, Insurance, Secure Info\n  * Implement SSN masking with visibility toggle\n  * Add vital badges (Age, Gender, Blood Type, MRN)\n  * Add insurance status badges with primary/secondary/tertiary support\n  * Comprehensive responsive design with mobile breakpoints\n  * Add data reference documentation\n\n- Frontend - Shell/Dashboard: Fix demographics access pattern\n  * Update dashboard.component.ts methods to use structured demographics object\n  * Fix getMRN, getDOB, getPatientAge, getPatientGender methods\n  * Remove deprecated getDemographicValue array search method","tree":{"sha":"96114a8841259f1f6b6f2dc8a86706a2a6204ae6","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/trees/96114a8841259f1f6b6f2dc8a86706a2a6204ae6"},"url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/commits/d53e276bbb9bd553270698f73b7de9f88fa618e9","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/d53e276bbb9bd553270698f73b7de9f88fa618e9","node_id":"C_kwDORpn-rNoAKGQ1M2UyNzZiYmI5YmQ1NTMyNzA2OThmNzNiN2RlOWY4OGZhNjE4ZTk","parents":[{"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/4ff2c1bef99690b906ffae81b18092c92d6db4e5","sha":"4ff2c1bef99690b906ffae81b18092c92d6db4e5","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/4ff2c1bef99690b906ffae81b18092c92d6db4e5"}],"sha":"d53e276bbb9bd553270698f73b7de9f88fa618e9","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/d53e276bbb9bd553270698f73b7de9f88fa618e9"},{"author":null,"comments_url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/4ff2c1bef99690b906ffae81b18092c92d6db4e5/comments","commit":{"author":{"date":"2026-02-25T19:48:14Z","email":"dev@patientrecords.local","name":"Development Team"},"comment_count":0,"committer":{"date":"2026-02-25T19:48:14Z","email":"dev@patientrecords.local","name":"Development Team"},"message":"Remove unused spark-service and tests from project\n\n- Remove entire spark-service directory (unused microservice)\n- Remove backend/tests directory (no active test suite)\n- Remove coverage directory (associated with removed tests)\n- Remove .github/workflows/integration.yml (was for spark-service testing)\n- Remove spark-service references from:\n  * backend/server.js: Remove SPARK_SERVICE_URL constant and /api/provider-options endpoint\n  * backend/openapi.json: Remove /api/provider-options API definition\n  * docker-compose.override.postgres.yml: Remove spark-service service config\n- Update documentation:\n  * docs/CI-SECRETS.md: Mark as deprecated, system now uses MongoDB\n  * docs/modernization-plan.md: Update architecture (remove Delta Lake references)\n  * docs/modernization-plan-root.md: Update to reflect MongoDB + Express.js stack\n\nSystem now uses pure MongoDB architecture with clean API surface.\nAll tests pass: Backend APIs, Clinical data endpoints, Frontend modules.","tree":{"sha":"d3df14ee0813077d278d0b4661bcdfe39a987713","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/trees/d3df14ee0813077d278d0b4661bcdfe39a987713"},"url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/commits/4ff2c1bef99690b906ffae81b18092c92d6db4e5","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/4ff2c1bef99690b906ffae81b18092c92d6db4e5","node_id":"C_kwDORpn-rNoAKDRmZjJjMWJlZjk5NjkwYjkwNmZmYWU4MWIxODA5MmM5MmQ2ZGI0ZTU","parents":[{"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/412952754cab1d29b564383212ca7ec32af68fff","sha":"412952754cab1d29b564383212ca7ec32af68fff","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/412952754cab1d29b564383212ca7ec32af68fff"}],"sha":"4ff2c1bef99690b906ffae81b18092c92d6db4e5","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/4ff2c1bef99690b906ffae81b18092c92d6db4e5"},{"author":null,"comments_url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/412952754cab1d29b564383212ca7ec32af68fff/comments","commit":{"author":{"date":"2026-02-25T19:00:30Z","email":"dev@patientrecords.local","name":"Development Team"},"comment_count":0,"committer":{"date":"2026-02-25T19:00:30Z","email":"dev@patientrecords.local","name":"Development Team"},"message":"Update README with shareable patient URLs and Observable pattern features\n\n- Add shareable URLs to key capabilities\n- Document URL-based patient routing pattern\n- Describe cross-module Observable synchronization\n- Add varied test patient data\n- Update roadmap to reflect Phase 6a completion\n- Update latest commit reference to cdcb4d1","tree":{"sha":"9f6a7eeb6fccf89254f3396b13e6a471c91d3456","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/trees/9f6a7eeb6fccf89254f3396b13e6a471c91d3456"},"url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/commits/412952754cab1d29b564383212ca7ec32af68fff","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/412952754cab1d29b564383212ca7ec32af68fff","node_id":"C_kwDORpn-rNoAKDQxMjk1Mjc1NGNhYjFkMjliNTY0MzgzMjEyY2E3ZWMzMmFmNjhmZmY","parents":[{"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/cdcb4d1516050d5b0e8fbade1a437158270aab2b","sha":"cdcb4d1516050d5b0e8fbade1a437158270aab2b","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/cdcb4d1516050d5b0e8fbade1a437158270aab2b"}],"sha":"412952754cab1d29b564383212ca7ec32af68fff","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/412952754cab1d29b564383212ca7ec32af68fff"},{"author":null,"comments_url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/cdcb4d1516050d5b0e8fbade1a437158270aab2b/comments","commit":{"author":{"date":"2026-02-25T17:54:32Z","email":"dev@patientrecords.local","name":"Development Team"},"comment_count":0,"committer":{"date":"2026-02-25T17:54:32Z","email":"dev@patientrecords.local","name":"Development Team"},"message":"Implement shareable patient URLs with Observable pattern across all modules\n\nFeatures:\n- Add URL-based patient routing: /dashboard/:module/:patientId\n- Patient selection updates URL and stays on current tab\n- Login preserves and redirects to originally requested URL\n- Dashboard syncs patient from URL on both initial load and route changes\n\nModule Updates:\n- Implement Observable pattern (interval 500ms) on all modules:\n  * Demographics, Vitals, Labs, Medications, Visits\n- All modules watch localStorage.__PATIENT_CONTEXT__ for patient changes\n- Auto-reload data when patient context changes\n- Fix patientId type conversion (String) for proper equality checks\n\nDashboard Enhancements:\n- Extract patient demographics from demographics array\n- Add MRN field (uses patientId if not in demographics)\n- Add debug logging for patient loading\n- Use navigateByUrl() instead of navigate() for URL preservation\n\nBackend Updates:\n- Add MRN to demographics array in patient GET endpoint\n- Create varied seed data script (seed-varied-patients.js)\n- Different vitals, labs, medications, and visits per patient\n- Fix visits schema to match backend expectations\n\nThis enables shareable patient URLs that can be copied/pasted to colleagues\nand will load the correct patient and module view.","tree":{"sha":"994ef6455b2a915edffb38793289624e55659f68","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/trees/994ef6455b2a915edffb38793289624e55659f68"},"url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/commits/cdcb4d1516050d5b0e8fbade1a437158270aab2b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/cdcb4d1516050d5b0e8fbade1a437158270aab2b","node_id":"C_kwDORpn-rNoAKGNkY2I0ZDE1MTYwNTBkNWIwZThmYmFkZTFhNDM3MTU4MjcwYWFiMmI","parents":[{"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/3e39c1a132041f90397ad10fc02687135e033f7c","sha":"3e39c1a132041f90397ad10fc02687135e033f7c","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/3e39c1a132041f90397ad10fc02687135e033f7c"}],"sha":"cdcb4d1516050d5b0e8fbade1a437158270aab2b","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/cdcb4d1516050d5b0e8fbade1a437158270aab2b"},{"author":null,"comments_url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/commits/3e39c1a132041f90397ad10fc02687135e033f7c/comments","commit":{"author":{"date":"2026-02-24T20:43:05Z","email":"dev@patientrecords.local","name":"Development Team"},"comment_count":0,"committer":{"date":"2026-02-24T20:43:05Z","email":"dev@patientrecords.local","name":"Development Team"},"message":"Implement Angular Observable pattern for patient change detection in demographics","tree":{"sha":"b058e52de67008f6257860e6a27167b05bfe0e50","url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/trees/b058e52de67008f6257860e6a27167b05bfe0e50"},"url":"https://api.github.com/repos/jabbour-labs/patientrecords.pub/git/commits/3e39c1a132041f90397ad10fc02687135e033f7c","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":null,"html_url":"https://github.com/jabbour-labs/patientrecords.pub/commit/3e39c1a132041f90397ad10fc02687135e033f7c","node_id":"C_kwDORpn-rNoAKDNlMzljMWExMzIwNDFmOTAzOTdhZDEw